class Solution {
public:
    bool isValidDigitNumber(int n, int x) {
        bool found = false;
        int lead = n % 10;
        while (n > 0) {
            int d = n % 10;
            if (d == x) found = true;
            lead = d;
            n /= 10;
        }
        return found && lead != x;
    }
};

