c.javascript:
var isValidDigitNumber = function(n, x) {
    let found = false, lead = n % 10;
    while (n > 0) {
        const d = n % 10;
        if (d === x) found = true;
        lead = d;
        n = Math.floor(n / 10);
    }
    return found && lead !== x;
};
